// Generated by muten (native-kit/muten-hermes.js): the check's JavaScript made to lack what Hermes lacks. The check runs
// in Node (V8), which has the whole Intl; a phone runs Hermes, which has only part of it, so a screen calling
// `new Intl.RelativeTimeFormat` passed the check and crashed on the phone ("undefined cannot be used as a constructor").
// What Hermes has, from its own list (https://github.com/facebook/hermes/blob/main/doc/IntlAPIs.md): Intl.Collator,
// Intl.NumberFormat and Intl.DateTimeFormat (format and resolvedOptions; formatToParts only on Android, and only for
// NumberFormat), and Intl.getCanonicalLocales. Everything else goes, unless the app brought its polyfill.
const HERMES_INTL = new Set(['Collator', 'NumberFormat', 'DateTimeFormat', 'getCanonicalLocales']);
for (const name of Object.getOwnPropertyNames(Intl)) if (!HERMES_INTL.has(name)) delete Intl[name];
delete Intl.DateTimeFormat.prototype.formatToParts;
delete Intl.DateTimeFormat.prototype.formatRange;

// React Native's own URL and URLSearchParams (simpler than Node's: parsed with regular expressions), so the data layer
// runs here against the one it meets on the phone
const rnUrl = require('react-native/Libraries/Blob/URL');
globalThis.URL = rnUrl.URL;
globalThis.URLSearchParams = rnUrl.URLSearchParams;
